<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useAuthStore} from '@/stores/auth'
import FrequencySourceEditor from '@/components/FrequencySourceEditor.vue'
import {useRoute} from 'vue-router'
import {coaching,type Overview} from '@/api/coaching'
import {messageOf} from '@/api/client'
import KnowledgeMindMap from '@/components/KnowledgeMindMap.vue'
const auth=useAuthStore(),route=useRoute(),data=ref<Overview>(),selected=ref(''),query=ref(''),error=ref('')
const point=computed(()=>data.value?.Points.find(p=>p.ID===selected.value))
const subjects=computed(()=>[...new Map((data.value?.Points??[]).map(p=>[p.SubjectID,p.SubjectName])).entries()].sort((a,b)=>['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(a[1])-['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(b[1])))
onMounted(async()=>{try{data.value=await coaching.overview();selected.value=typeof route.query.point==='string'?route.query.point:data.value.Points.find(p=>p.Code==='DS.BASIC')?.ID??data.value.Points[0]?.ID??''}catch(e){error.value=messageOf(e)}})
</script>
<template><div><header class="page-head"><div><h1>408 知识思维导图</h1><p>这里查看知识结构和详细概念；学习安排在“学习任务”，测评结果在“测评学情”。</p></div></header><p v-if="error" class="notice error">{{error}}</p><section class="map-grid"><div class="card section"><input v-model="query" placeholder="搜索知识点" aria-label="搜索知识点"/><div v-if="query" class="toolbar-actions"><button v-for="p in data?.Points.filter(p=>p.Name.includes(query))??[]" :key="p.ID" class="secondary" @click="selected=p.ID">{{p.Name}}</button></div><div v-else class="map-tree"><details v-for="[id,name] in subjects" :key="id" open><summary>{{name}}</summary><KnowledgeMindMap :points="data?.Points??[]" :subject="id" @select="selected=$event"/></details></div></div><article v-if="point" class="card section"><h2>{{point.Name}}</h2><p>{{point.Description}}</p><p>{{point.State}} · 已测{{point.Tested}}个题组 · 可练习{{point.AvailableQuestions}}组</p><p>参考重要性 {{point.Importance.toFixed(1)}} / 5</p><p class="muted">{{point.ImportanceBasis}}</p><p>库内真题：{{point.ExamYears}} / {{point.CorpusYears}}个本学科已识别年度，不是未来考频预测。</p><details><summary>机构来源对比（{{point.Sources.length}}）</summary><p v-if="!point.Sources.length">尚未录入经核对的机构报告。</p><article v-for="f in point.Sources" :key="f.ID"><b>{{f.Organization}} · {{f.StartYear}}–{{f.EndYear}}</b><p>{{f.Appearances}} / {{f.Exams}}个年度</p><a :href="f.URL" target="_blank" rel="noopener noreferrer">{{f.Title}}</a><blockquote>{{f.Excerpt}}</blockquote></article></details><FrequencySourceEditor v-if="auth.user?.role==='admin'" :point-id="point.ID" @saved="coaching.overview().then(v=>data=v).catch(e=>error=messageOf(e))"/><div class="toolbar-actions"><RouterLink :to="{path:'/exam408/tasks',query:{tab:'teacher',point:point.ID}}">请老师讲解</RouterLink><RouterLink :to="{path:'/exam408/assets',query:{point:point.ID}}">该点题库</RouterLink><RouterLink :to="{path:'/exam408/assessment',query:{point:point.ID}}">专项练习</RouterLink></div></article></section></div></template>
<style scoped>.map-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;align-items:start}.map-tree{max-height:680px;overflow:auto;padding:12px 0}.map-tree>details{margin:16px 0}.map-tree>details>summary{font-weight:600;cursor:pointer}.map-grid p{line-height:1.8}@media(max-width:800px){.map-grid{grid-template-columns:1fr}}</style>
